/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { FpGroup, FreeGroup, Perm, PermutationGroup, symbols } from '../src';
import { sympyStr } from './sympy-str';

describe("sympy/combinatorics/tests/test_rewriting.py", () => {
  it("test_rewriting:13", () => {
    const [a, b] = symbols('a b');
    const v1 = new FreeGroup([a, b]);
    expect(sympyStr(new FpGroup(v1, [v1.dtype([[a, 1], [b, 1], [a, -1], [b, -1]])]).reduce(new FreeGroup([a, b]).dtype([[b, -1], [a, 1]])))).toBe('a*b**-1');
  });
  it("test_rewriting:14", () => {
    const [a, b] = symbols('a b');
    const v1 = new FreeGroup([a, b]);
    expect(sympyStr(new FpGroup(v1, [v1.dtype([[a, 1], [b, 1], [a, -1], [b, -1]])]).reduce(new FreeGroup([a, b]).dtype([[b, 3], [a, 4], [b, -2], [a, 1]])))).toBe('a**5*b');
  });
  it("test_rewriting:15", () => {
    const [a, b] = symbols('a b');
    const v1 = new FreeGroup([a, b]);
    expect(sympyStr(new FpGroup(v1, [v1.dtype([[a, 1], [b, 1], [a, -1], [b, -1]])]).equals(new FreeGroup([a, b]).dtype([[b, 2], [a, -1], [b, 1]]), new FreeGroup([a, b]).dtype([[b, 4], [a, -1], [b, -1]])))).toBe('True');
  });
  it("test_rewriting:29", () => {
    const [a, b] = symbols('a b');
    const v1 = new FreeGroup([a, b]);
    expect(sympyStr(new FpGroup(v1, [new FreeGroup([a, b]).dtype([[a, 3]]), new FreeGroup([a, b]).dtype([[b, 3]]), v1.dtype([[a, 1], [b, 1], [a, 1], [b, 1]])]).reduce(new FreeGroup([a, b]).dtype([[b, 1], [a, -1], [b, -1], [a, 3], [b, 4], [a, -1], [b, -15]])))).toBe('a**-1*b**-1');
  });
  it("test_rewriting:35", () => {
    const [a, b] = symbols('a b');
    const v1 = new FreeGroup([a, b]);
    expect(sympyStr(new FpGroup(v1, [new FreeGroup([a, b]).dtype([[a, 2]]), new FreeGroup([a, b]).dtype([[b, 3]]), v1.dtype([[a, 1], [b, 1], [a, 1], [b, 1], [a, 1], [b, 1], [a, 1], [b, 1]])]).reduce(new FreeGroup([a, b]).dtype([[a, 2], [b, -2], [a, 2], [b, 1]])))).toBe('b**-1');
  });
  it("test_rewriting:37", () => {
    const [a, b] = symbols('a b');
    const v1 = new FreeGroup([a, b]);
    expect(sympyStr(new FpGroup(v1, [new FreeGroup([a, b]).dtype([[a, 2]]), new FreeGroup([a, b]).dtype([[b, 3]]), v1.dtype([[a, 1], [b, 1], [a, 1], [b, 1], [a, 1], [b, 1], [a, 1], [b, 1]])]).reduce(new FreeGroup([a, b]).dtype([[a, 3], [b, -2], [a, 2], [b, 1]])))).toBe('a**-1*b**-1');
  });
});

describe("sympy/combinatorics/tests/test_testutil.py", () => {
  it("test_naive_list_centralizer:24", () => {
    expect(sympyStr(PermutationGroup([new Perm([1, 2, 0]), new Perm([2, 0, 1])]).isSubgroup(PermutationGroup([new Perm([1, 2, 0])])))).toBe('True');
  });
});
